use std::time::Duration;
use std::thread;

/// Retry a fallible operation with exponential backoff.
///
/// - `max_retries`: maximum number of attempts (0 means try once, no retries)
/// - `initial_delay`: base delay before first retry
/// - `max_delay`: cap on the backoff duration
/// - `op`: the operation to retry; receives the current attempt number (0-indexed)
///
/// Returns `Ok(T)` on first success, or the last `Err(E)` after all attempts are exhausted.
pub fn retry_with_backoff<T, E, F>(
    max_retries: u32,
    initial_delay: Duration,
    max_delay: Duration,
    mut op: F,
) -> Result<T, E>
where
    F: FnMut(u32) -> Result<T, E>,
{
    let total_attempts = max_retries.saturating_add(1); // avoid overflow if max_retries == u32::MAX
    let mut last_err: Option<E> = None;

    for attempt in 0..total_attempts {
        match op(attempt) {
            Ok(val) => return Ok(val),
            Err(e) => {
                last_err = Some(e);

                // Don't sleep after the final attempt
                if attempt < max_retries {
                    let exp = attempt.min(63); // prevent shift overflow (2^63 is already huge)
                    let backoff = initial_delay.saturating_mul(2u32.saturating_pow(exp));
                    let capped = backoff.min(max_delay);
                    thread::sleep(capped);
                }
            }
        }
    }

    // total_attempts >= 1, so last_err is always Some
    Err(last_err.unwrap())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;
    use std::time::Instant;

    #[test]
    fn succeeds_immediately() {
        let result = retry_with_backoff(3, Duration::from_millis(10), Duration::from_secs(1), |_| {
            Ok::<_, &str>(42)
        });
        assert_eq!(result, Ok(42));
    }

    #[test]
    fn fails_then_succeeds() {
        let count = Cell::new(0);
        let result = retry_with_backoff(5, Duration::from_millis(1), Duration::from_secs(1), |_| {
            let c = count.get();
            count.set(c + 1);
            if c < 3 {
                Err("not yet")
            } else {
                Ok("done")
            }
        });
        assert_eq!(result, Ok("done"));
        assert_eq!(count.get(), 4);
    }

    #[test]
    fn exhausts_all_retries() {
        let count = Cell::new(0u32);
        let result = retry_with_backoff(2, Duration::from_millis(1), Duration::from_millis(10), |_| {
            count.set(count.get() + 1);
            Err::<(), _>("always fails")
        });
        assert_eq!(result, Err("always fails"));
        assert_eq!(count.get(), 3); // 1 initial + 2 retries
    }

    #[test]
    fn zero_retries_means_single_attempt() {
        let count = Cell::new(0u32);
        let result = retry_with_backoff(0, Duration::from_millis(100), Duration::from_secs(1), |_| {
            count.set(count.get() + 1);
            Err::<(), _>("fail")
        });
        assert_eq!(result, Err("fail"));
        assert_eq!(count.get(), 1);
    }

    #[test]
    fn respects_max_delay_cap() {
        let start = Instant::now();
        let _ = retry_with_backoff(3, Duration::from_secs(100), Duration::from_millis(5), |_| {
            Err::<(), _>("fail")
        });
        let elapsed = start.elapsed();
        // 3 sleeps capped at 5ms each = ~15ms, definitely under 1s
        assert!(elapsed < Duration::from_secs(1));
    }
}
```

Edge cases handled:

- `max_retries = 0` — runs the operation exactly once, no sleep.
- `max_retries = u32::MAX` — `saturating_add` prevents overflow when computing total attempts.
- Large exponents — `attempt.min(63)` prevents bit-shift overflow in `2^n`.
- Huge `initial_delay` — `saturating_mul` clamps to `Duration::MAX` instead of panicking, then `min(max_delay)` brings it back down.
- No sleep after the final failed attempt — avoids a pointless wait when we're about to return the error.
- Attempt index passed to the closure — lets callers log or adjust behavior per attempt.

If you need async, swap `thread::sleep` for `tokio::time::sleep(...).await` and make the closure `async`. The backoff logic stays identical.

Here's a practical test suite for a nested JSON parser. I'll assume we're testing a `parseNestedJson` function that takes a string and returns a parsed object, with proper error handling.

```typescript
import { describe, it, expect } from 'vitest';
import { parseNestedJson } from './parseNestedJson';

describe('parseNestedJson', () => {
  // --- Happy path ---

  it('parses a flat object', () => {
    const input = '{"name": "Alice", "age": 30}';
    expect(parseNestedJson(input)).toEqual({ name: 'Alice', age: 30 });
  });

  it('parses deeply nested objects', () => {
    const input = '{"a": {"b": {"c": {"d": "deep"}}}}';
    const result = parseNestedJson(input);
    expect(result.a.b.c.d).toBe('deep');
  });

  it('parses nested arrays', () => {
    const input = '{"matrix": [[1, 2], [3, 4]]}';
    expect(parseNestedJson(input)).toEqual({ matrix: [[1, 2], [3, 4]] });
  });

  it('parses mixed nested structures', () => {
    const input = '{"users": [{"name": "Bob", "tags": ["admin", "active"]}]}';
    const result = parseNestedJson(input);
    expect(result.users[0].name).toBe('Bob');
    expect(result.users[0].tags).toContain('admin');
  });

  it('handles all JSON primitive types', () => {
    const input = '{"str": "hello", "num": 42, "float": 3.14, "bool": true, "nil": null}';
    const result = parseNestedJson(input);
    expect(result.str).toBe('hello');
    expect(result.num).toBe(42);
    expect(result.float).toBeCloseTo(3.14);
    expect(result.bool).toBe(true);
    expect(result.nil).toBeNull();
  });

  it('handles empty objects and arrays', () => {
    const input = '{"empty_obj": {}, "empty_arr": []}';
    expect(parseNestedJson(input)).toEqual({ empty_obj: {}, empty_arr: [] });
  });

  // --- Edge cases ---

  it('handles unicode and escaped characters', () => {
    const input = '{"msg": "hello\\nworld", "emoji": "\\u2603"}';
    const result = parseNestedJson(input);
    expect(result.msg).toBe('hello\nworld');
    expect(result.emoji).toBe('☃');
  });

  it('handles keys with special characters', () => {
    const input = '{"foo.bar": 1, "baz qux": 2, "": 3}';
    const result = parseNestedJson(input);
    expect(result['foo.bar']).toBe(1);
    expect(result['baz qux']).toBe(2);
    expect(result['']).toBe(3);
  });

  it('handles large numeric values', () => {
    const input = '{"big": 9007199254740991}';
    expect(parseNestedJson(input).big).toBe(Number.MAX_SAFE_INTEGER);
  });

  // --- Depth limits (if your parser enforces them) ---

  it('rejects nesting beyond max depth', () => {
    const depth = 128;
    const input = '{' + '"a":'.repeat(depth) + '1' + '}'.repeat(depth);
    expect(() => parseNestedJson(input, { maxDepth: 64 })).toThrow(/depth/i);
  });

  // --- Error handling ---

  it('throws on invalid JSON', () => {
    expect(() => parseNestedJson('{not json}')).toThrow();
  });

  it('throws on trailing commas', () => {
    expect(() => parseNestedJson('{"a": 1,}')).toThrow();
  });

  it('throws on single quotes', () => {
    expect(() => parseNestedJson("{'a': 1}")).toThrow();
  });

  it('throws on empty string input', () => {
    expect(() => parseNestedJson('')).toThrow();
  });

  it('throws on non-string input', () => {
    // @ts-expect-error testing runtime guard
    expect(() => parseNestedJson(undefined)).toThrow();
    // @ts-expect-error testing runtime guard
    expect(() => parseNestedJson(123)).toThrow();
  });

  it('throws on unclosed brackets', () => {
    expect(() => parseNestedJson('{"a": {"b": 1}')).toThrow();
  });
});
```

Key decisions in this test suite:

- Tests are grouped by concern: happy path, edge cases, depth limits, error handling.
- Each test checks one specific behavior — easy to diagnose failures.
- The depth limit test assumes an optional `maxDepth` config. If your parser doesn't have one, drop it or add it (you should — unbounded recursion is a DoS vector).
- Error tests verify the parser rejects malformed input rather than silently returning garbage.

Adapt the import path and function signature to match your actual implementation. If you're writing the parser from scratch (not wrapping `JSON.parse`), you'll also want tests for streaming/partial input and performance benchmarks on large payloads.
